"""Writes the readable docs (RUBRIC.md, PERSONAS.md) from the YAML test material."""

from mirrorguard.library.loader import Library
from mirrorguard.library.schemas import Persona, Scenario

GENERATED_NOTE = (
    "<!-- Generated by `mirrorguard export-docs`. Edit the YAML files, not this file. -->"
)


def _bullets(items: list[str]) -> list[str]:
    return [f"- {item}" for item in items]


def render_rubric(library: Library) -> str:
    rubric = library.rubric
    lines = [
        GENERATED_NOTE,
        "",
        "# Scoring rubric",
        "",
        f"Rubric version: {rubric.version}",
        "",
        "Every measure is scored from 0 to 1. **0 is good (honest), 1 is bad (sycophantic).**",
        "The Sycophancy Risk Score is the weighted average of the measures.",
        "",
        "The weights are a starting point. They are reviewed in Phase 3 against human labels.",
        "",
        "| Measure | Weight | Scored per | Question the judge answers |",
        "|---|---|---|---|",
    ]
    for m in rubric.measures:
        lines.append(f"| {m.name} | {m.weight:.2f} | {m.level} | {m.question} |")
    lines += ["", "## What the scores mean", ""]
    for m in rubric.measures:
        lines += [f"### {m.name} (`{m.id}`)", ""]
        if m.applies_when == "escalation_expected":
            lines += ["Scored only in scenarios where pointing to real help is expected.", ""]
        lines += [
            "| Score | What it looks like |",
            "|---|---|",
            f"| 0 | {m.anchors.zero} |",
            f"| 0.5 | {m.anchors.half} |",
            f"| 1 | {m.anchors.one} |",
            "",
        ]
    return "\n".join(lines).rstrip() + "\n"


def _render_scenario(scenario: Scenario) -> list[str]:
    lines = [
        f"#### {scenario.title} (`{scenario.id}`)",
        "",
        f"**Opening message:** {scenario.opening_message}",
        "",
        f"**What the user wants:** {scenario.user_goal}",
        "",
        "**A sycophantic reply would:**",
        "",
        *_bullets(scenario.sycophantic_reply_would),
        "",
        "**An honest reply should:**",
        "",
        *_bullets(scenario.honest_reply_should),
        "",
        "**Pushback lines:**",
        "",
        *_bullets(scenario.pushback_lines),
        "",
    ]
    facts = [f"{scenario.turns} turns", f"language `{scenario.language}`"]
    if scenario.escalation_expected:
        facts.append("pointing to real help is expected")
    if scenario.matched_control:
        facts.append(f"matched control `{scenario.matched_control}`")
    lines += ["*" + "; ".join(facts) + "*", ""]
    return lines


def _render_persona(persona: Persona, library: Library) -> list[str]:
    kind = "control" if persona.is_control else persona.vulnerability_state.value
    lines = [
        f"## {persona.name} (`{persona.id}`)",
        "",
        f"**Type:** {kind}",
        "",
        persona.summary,
        "",
        f"**Background:** {persona.background}",
        "",
        f"**How they talk:** {persona.speaking_style}",
        "",
        f"**Core belief:** {persona.core_belief}",
        "",
    ]
    if persona.risk_signals:
        lines += ["**Risk signals:**", "", *_bullets(persona.risk_signals), ""]
    lines += [
        "**How they push back:**",
        "",
        *_bullets(persona.pressure_tactics),
        "",
        "**How they change over the conversation:**",
        "",
        f"- Early: {persona.arc.early}",
        f"- Middle: {persona.arc.middle}",
        f"- Late: {persona.arc.late}",
        "",
        "### Scenarios",
        "",
    ]
    for scenario in library.scenarios_for(persona.id):
        lines += _render_scenario(scenario)
    return lines


def render_personas(library: Library) -> str:
    lines = [
        GENERATED_NOTE,
        "",
        "# Personas and scenarios",
        "",
        "All personas are synthetic. They are not based on any real person.",
        "They describe patterns of talking, not diagnoses, and they need review by a",
        "psychology expert before the benchmark results are published.",
        "",
        f"There are {len(library.personas)} personas and {len(library.scenarios)} scenarios.",
        "",
    ]
    ordered = sorted(library.personas.values(), key=lambda p: (not p.is_control, p.id))
    for persona in ordered:
        lines += _render_persona(persona, library)
    return "\n".join(lines).rstrip() + "\n"
